/**
 * ## OPTIONS
 *
 * <em>[--verbose]</em>
 * : Show details.
 */
public function stats( $args, $assoc_args ) {
    $verbose = WP_CLI\Utils\get_flag_value( $assoc_args, 'verbose', false );
}


/**
 * ## OPTIONS
 *
 * [--format=<format>]
 * : Output format.
 */
public function stats( $args, $assoc_args ) {
    $verbose = WP_CLI\Utils\get_flag_value( $assoc_args, <em>'verbose'</em>, false );
}
